-- SYNTHETIC TEST DATABASE ONLY. Never apply this fixture to Supabase.
-- All account IDs and rows below are fabricated. The detector source is retained
-- as a behavior fixture; public schema/permissions and the private ledger below
-- are deliberately minimal, not a restoration or export of a live database.
-- The test loader canonicalizes newlines to CRLF before PostgreSQL stores function
-- bodies, keeping the catalog fingerprints stable across checkout platforms.
create role anon nologin;
create role authenticated nologin;
create role service_role nologin;
create schema auth;
create table auth.users(id uuid primary key);
insert into auth.users values ('11111111-1111-4111-8111-111111111111');
create function auth.uid() returns uuid language sql stable as $$
  select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid;
$$;
grant usage on schema auth, public to anon, authenticated, service_role;

create schema tapflow_internal;
create table tapflow_internal.r1_room_episode (
  room_id integer primary key,
  alert_id bigint,
  after_at timestamptz not null default now(),
  last_observed_at timestamptz
);

create table public.flow_readings (
  id bigint generated always as identity primary key,
  device_id text not null check (device_id in ('main', 'room1', 'room2', 'room3')),
  pulses integer check (pulses >= 0),
  sample_ms integer check (sample_ms > 0),
  flow_lpm numeric(10,3) check (flow_lpm >= 0),
  valve_open boolean,
  r1_received_at timestamptz not null default now()
);
create table public.room_status (
  room_id smallint primary key check (room_id between 1 and 3),
  rfid_active boolean not null default false,
  valve_commanded_on boolean not null default false,
  last_seen_at timestamptz,
  updated_at timestamptz not null default now()
);
create table public.tapflow_r1_alerts (
  id bigint generated by default as identity primary key,
  room_id integer not null default 1 check (room_id between 1 and 3),
  code text not null default 'R1_MISSING_FLOW_SIGNAL',
  status text not null default 'ACTIVE' check (status in ('ACTIVE', 'RESOLVED')),
  detected_at timestamptz not null default now(),
  resolved_at timestamptz,
  evidence jsonb not null default '{}'::jsonb
);
alter table public.flow_readings enable row level security;
alter table public.room_status enable row level security;
alter table public.tapflow_r1_alerts enable row level security;
create policy tapflow_r1_authorized_viewer on public.tapflow_r1_alerts
  for select to authenticated
  using (auth.uid() = '11111111-1111-4111-8111-111111111111'::uuid);
grant select on public.tapflow_r1_alerts to authenticated;

CREATE OR REPLACE FUNCTION public.tapflow_r1_after_flow_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  candidate record;
  episode tapflow_internal.r1_room_episode%ROWTYPE;
  candidate_device text;
  main_last timestamptz;
  room_last timestamptz;
  positive_pair boolean;
  zero_pair boolean;
  new_alert_id bigint;
BEGIN
  SELECT max(f.r1_received_at) INTO main_last
  FROM (
    SELECT r.r1_received_at, r.flow_lpm
    FROM public.flow_readings AS r
    WHERE r.device_id = 'main'
      AND r.sample_ms BETWEEN 10000 AND 30000
      AND r.r1_received_at >= now() - interval '90 seconds'
    ORDER BY r.id DESC
    LIMIT 2
  ) AS f
  HAVING count(*) = 2
     AND bool_and(f.flow_lpm IS NOT NULL AND f.flow_lpm > 0.5)
     AND max(f.r1_received_at) >= now() - interval '35 seconds'
     AND max(f.r1_received_at) - min(f.r1_received_at) >= interval '10 seconds';

  FOR candidate IN
    SELECT active.*
    FROM (
      SELECT s.room_id, count(*) OVER () AS active_room_count
      FROM public.room_status AS s
      WHERE s.room_id IN (1, 2, 3)
        AND s.rfid_active IS TRUE
        AND s.valve_commanded_on IS TRUE
    ) AS active
    WHERE NEW.device_id = 'main'
       OR NEW.device_id = 'room' || active.room_id::text
    ORDER BY active.room_id
  LOOP
    candidate_device := 'room' || candidate.room_id::text;

    INSERT INTO tapflow_internal.r1_room_episode (room_id)
    VALUES (candidate.room_id)
    ON CONFLICT (room_id) DO NOTHING;

    SELECT * INTO STRICT episode
    FROM tapflow_internal.r1_room_episode
    WHERE room_id = candidate.room_id
    FOR UPDATE;

    SELECT max(f.r1_received_at), bool_and(f.pulses > 0), bool_and(f.pulses = 0)
    INTO room_last, positive_pair, zero_pair
    FROM (
      SELECT r.r1_received_at, r.pulses, r.valve_open
      FROM public.flow_readings AS r
      WHERE r.device_id = candidate_device
        AND r.sample_ms BETWEEN 10000 AND 30000
        AND r.r1_received_at >= now() - interval '90 seconds'
        AND r.r1_received_at > episode.after_at
      ORDER BY r.id DESC
      LIMIT 2
    ) AS f
    HAVING count(*) = 2
       AND bool_and(f.valve_open IS TRUE AND f.pulses IS NOT NULL)
       AND max(f.r1_received_at) >= now() - interval '35 seconds'
       AND max(f.r1_received_at) - min(f.r1_received_at) >= interval '10 seconds';

    IF NOT FOUND THEN
      CONTINUE;
    END IF;

    -- Recovery allows a new episode without closing the old incident.
    IF episode.alert_id IS NOT NULL AND positive_pair
       AND NEW.device_id = candidate_device
       AND (episode.last_observed_at IS NULL OR room_last > episode.last_observed_at)
    THEN
      UPDATE tapflow_internal.r1_room_episode
      SET alert_id = NULL, after_at = room_last, last_observed_at = NULL
      WHERE room_id = candidate.room_id;
      CONTINUE;
    END IF;

    IF NOT zero_pair OR main_last IS NULL
       OR abs(extract(epoch FROM (room_last - main_last))) > 25
    THEN
      CONTINUE;
    END IF;

    IF episode.alert_id IS NULL THEN
      INSERT INTO public.tapflow_r1_alerts (room_id, code, status, evidence)
      VALUES (
        candidate.room_id,
        'R1_MISSING_FLOW_SIGNAL',
        'ACTIVE',
        jsonb_build_object(
          'main_flow_threshold_lpm', 0.5,
          'main_sample_count', 2,
          'room_sample_count', 2,
          'main_latest_at', main_last,
          'room_latest_at', room_last,
          'last_observed_at', room_last,
          'active_room_count', candidate.active_room_count,
          'note', 'Main measures combined flow. Confirm water is flowing at this room outlet before checking the sensor signal.'
        )
      )
      RETURNING id INTO new_alert_id;

      UPDATE tapflow_internal.r1_room_episode
      SET alert_id = new_alert_id, last_observed_at = room_last
      WHERE room_id = candidate.room_id;
    ELSIF episode.last_observed_at IS NULL OR room_last > episode.last_observed_at THEN
      UPDATE public.tapflow_r1_alerts
      SET evidence = coalesce(evidence, '{}'::jsonb)
                     || jsonb_build_object('last_observed_at', room_last)
      WHERE id = episode.alert_id AND status = 'ACTIVE';

      UPDATE tapflow_internal.r1_room_episode
      SET last_observed_at = room_last
      WHERE room_id = candidate.room_id;
    END IF;
  END LOOP;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.tapflow_update_status_timestamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
    NEW.updated_at = NOW();
    NEW.last_seen_at = NOW();
    RETURN NEW;
END;
$function$;

CREATE TRIGGER tapflow_r1_flow_insert_trigger AFTER INSERT ON flow_readings FOR EACH ROW WHEN ((new.device_id = ANY (ARRAY['main'::text, 'room1'::text, 'room2'::text, 'room3'::text])) AND new.sample_ms >= 10000 AND new.sample_ms <= 30000) EXECUTE FUNCTION tapflow_r1_after_flow_insert();
CREATE TRIGGER tapflow_status_timestamp_trigger BEFORE UPDATE ON room_status FOR EACH ROW EXECUTE FUNCTION tapflow_update_status_timestamp();

